import {SIZES,WALL_SIZE,TOTAL_PIXELS,STORAGE_KEY,freshState,stats,money,minimumBid,safeUrl,validateAd,reserve,cancelReservation,startAuction,placeBid,expire,simulatePayment,submitAd,approveAd,rejectAd,estimateRevenue,canPlace,selectPlacement,releasePlacement} from './model.mjs';

const $=s=>document.querySelector(s), main=$('#main-content'), modal=$('#modal');
let selectedSize='small',selectionAnchor=null;
let state=freshState(),zoom=1,wallFilter='all',directoryFilter='all',search='',uploadedImage=null,toastTimer;
let checkoutLot=null,returnAction=null,activeDialog=null,afterNavigation=null;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=()=>location.hash.slice(1).split('?')[0]||'wall';
const amount=n=>escape(money(n));
const statusText=s=>({'available':'Available','upcoming':'Auction queue','active':'Bidding open','reserved':'In checkout','awaiting-payment':'Winner payment pending','paid':'Ready for your ad','review':'Ad in review','published':'On the wall','hidden':'Ad hidden'}[s]||s);
const pill=(s,c='')=>`<span class="chip ${c}">${escape(s)}</span>`;
const action=(label,act,id='',cls='')=>`<button class="button ${cls}" data-action="${act}" ${id?`data-id="${escape(id)}"`:''}>${label}</button>`;
const ago=t=>{const m=Math.max(0,Math.floor((Date.now()-t)/60000));return m<1?'just now':m<60?`${m}m ago`:m<1440?`${Math.floor(m/60)}h ago`:`${Math.floor(m/1440)}d ago`;};
const remaining=t=>{const s=Math.max(0,Math.ceil((t-Date.now())/1000));return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{toast('Browser storage is full. Remove a large image or reset the demo.');return false;}}
function load(){try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY));if(s?.version===2&&Array.isArray(s.lots)&&Array.isArray(s.events)&&Array.isArray(s.reports)){state=s;expire(state);}}catch{state=freshState();}}
load();
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function find(id){const l=state.lots.find(l=>l.id===id);if(!l)throw Error('Block not found.');return l;}
function run(fn){try{return fn();}catch(e){toast(e.message);return null;}}
function commit(message){save();render();if(message)toast(message);}
function modalOpen(label,content,type='info'){activeDialog=type;$('#dialog-label').textContent=label;$('#modal-body').innerHTML=content;if(!modal.open)modal.showModal();}
function modalClose(){if(checkoutLot){cancelReservation(state,checkoutLot);releasePlacement(state,checkoutLot);checkoutLot=null;save();render();}modal.close();activeDialog=null;}
$('#close-modal').onclick=modalClose;
modal.addEventListener('cancel',e=>{e.preventDefault();modalClose();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modalClose();}});
window.addEventListener('hashchange',()=>{modalClose();render();window.scrollTo({top:0,behavior:'instant'});const next=afterNavigation;afterNavigation=null;next?.();});
$('#profile-button').onclick=()=>profileDialog();
$('#reset-demo').onclick=()=>modalOpen('RESET THIS BROWSER',`<h2 id="modal-title">A fresh canvas?</h2><p>This clears this browser’s demo profiles, bids, ads and simulated purchases. Your existing website and Firebase data are unaffected.</p><div class="dialog-actions">${action('Keep exploring','close','','ghost')}${action('Reset demo','reset-confirm','','dark')}</div>`);

function profileDialog(after){returnAction=after||null;modalOpen('DEMO PROFILE',`<h2 id="modal-title">Hello, internet person.</h2><p>Create a local profile to try buying a block, bidding and publishing an ad. This preview does not create a real account or collect an email address.</p><form id="profile-form"><div class="form-group"><label for="profile-name">YOUR DISPLAY NAME</label><input id="profile-name" name="name" minlength="2" maxlength="24" required autocomplete="nickname" placeholder="e.g. Studio Luna" value="${escape(state.user?.name||'')}"></div><button class="button dark full" type="submit">${state.user?'Update demo profile':'Create demo profile'} ↗</button></form><div class="notice blue">For review: switch between two test bidders to try a competitive auction.</div><div class="profile-choices">${action('Try as Alex','switch-user','alex','small ghost')}${action('Try as Sam','switch-user','sam','small ghost')}${state.user?action('Sign out locally','sign-out','','small ghost'):''}</div>`,'profile');}
function loginThen(fn){if(state.user)fn();else profileDialog(fn);}
function headerUpdate(){const owned=state.user?state.lots.filter(l=>l.owner===state.user.id).length:0;const wins=state.user?state.lots.filter(l=>l.status==='awaiting-payment'&&l.winner===state.user.id).length:0;$('#profile-button').textContent=state.user?`${state.user.name} ↗`:'Join the wall ↗';$('#notification-count').hidden=!wins;$('#notification-count').textContent=wins;document.querySelectorAll('[data-route]').forEach(a=>{const selected=a.dataset.route===route();a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function metrics(){const s=stats(state);return `<div class="metrics"><div class="metric"><div class="metric-label">THE WALL IS FILLING</div><div class="metric-value">${s.percent.toFixed(2)}<span style="font-size:16px">%</span></div><div class="progress" role="progressbar" aria-label="Demo paid pixel area" aria-valuenow="${s.percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${s.percent}%"></span></div><small>${s.paidPixels.toLocaleString()} / 1,000,000 pixels · demo</small></div><div class="metric"><div class="metric-label">CORNERS CLAIMED</div><div class="metric-value">${s.paidLots}<span class="muted" style="font-size:16px"></span></div><small>Simulated paid blocks only</small></div><div class="metric"><div class="metric-label">COLLECTED · DEMO</div><div class="metric-value">${amount(s.gross)}</div><small>Gross sales, before costs</small></div><div class="metric"><div class="metric-label">THE DAILY CHALLENGE</div><div class="metric-value">${state.campaignStart?`Day ${Math.floor((Date.now()-state.campaignStart)/86400000)+1}`:'Day zero'}</div><small>${state.campaignStart?'Fill the wall. Tell the story.':'The first paid block starts the clock.'}</small></div></div>`;}
function tierCards(){return `<div class="tier-grid">${Object.entries(SIZES).map(([key,t])=>`<article class="tier-card" style="--tier-bg:#dedede">${pill(key==='large'?'AUCTION':'BUY NOW')}<h3>${t.name} pixels</h3><p>Available to everyone, at any free location where it fits.</p><div class="tier-price">${key==='large'?'From ':''}${amount(t.price)}</div><small>12 months after confirmed payment</small>${action('Choose on the shared wall →','choose-wall-size',key,'dark')}</article>`).join('')}</div>`;}
function activeAuction(){return state.lots.find(l=>l.status==='active'||l.status==='awaiting-payment');}
function featureCard(){const a=activeAuction();return `<article class="feature-card"><div class="eyebrow">THE BIG SPOT</div><h2>A little competition.<br>A lot more room.</h2><p>100 × 100 pixels for a large with something to say.</p><div class="feature-art"><span class="block-label">YOUR BRAND<br>GOES HERE ↗</span></div><div class="countdown"><div><small>${a?.bids.length?'CURRENT BID':'STARTING AT'}</small><br><strong>${amount(a?.amount||500)}</strong></div><div><small>${a?.status==='active'?'ENDS IN':a?'PAYMENT':'NEXT DROP'}</small><br><strong ${a?.status==='active'?`data-countdown="${a.endsAt}"`:''}>${a?.status==='active'?remaining(a.endsAt):a?'PENDING':'SOON'}</strong></div></div><a class="button lime full" href="#auctions">${a?'View the auction':'Explore the auction'} ↗</a><p style="font-size:10px;margin-top:12px">One featured auction at a time. No charge to bid.</p></article>`;}
function wallPage(){return `<div class="wall-layout"><section id="grid-sec"><div id="gtb" class="wall-toolbar"><span class="tool-label">SELECT SIZE:</span>${Object.entries(SIZES).map(([key,t])=>`<button class="tab ${selectedSize===key?'active':''}" data-action="size-tool" data-id="${key}" aria-pressed="${selectedSize===key}">${t.name} · ${amount(t.price)}${key==='large'?' auction':''}</button>`).join('')}<span class="toolbar-spacer"></span><label for="goto-cell">Go to #</label><input id="goto-cell" type="number" min="0" max="1599" placeholder="0–1599" aria-label="Go to cell number"><button class="tab" data-action="goto-position">GO</button><button class="icon-button" data-action="zoom-out" aria-label="Zoom out">−</button><span class="zoom-label">${Math.round(zoom*100)}%</span><button class="icon-button" data-action="zoom-in" aria-label="Zoom in">+</button></div><div class="wall-scroll" id="wall-scroll"><div class="wall-canvas" id="wall-canvas" role="group" aria-label="Shared one million pixel wall. Choose any available position."></div></div><div class="wall-bottom"><span class="legend" style="--c:#ffffff"><i></i>Available · any size</span><span class="legend" style="--c:#2935a3"><i></i>Claimed</span><span class="legend" style="--c:#ffdd44"><i></i>Auction</span><span class="legend" style="--c:#cc0000"><i></i>Unavailable selection</span><span class="keyboard-hint">Click a free square to choose your position and size. Anyone can choose anywhere.</span></div></section><aside id="sidebar"><section class="panel"><div class="ptb"><span>📡 LIVE BID FEED</span><span>_ □</span></div><div class="retro-panel-body">${activityList(5)}</div></section><section class="panel"><div class="ptb"><span>💎 ACTIVE AUCTION</span><span>_</span></div><div class="retro-panel-body">${retroAuction()}</div></section><section class="panel"><div class="ptb"><span>🏆 TOP PIXEL OWNERS</span><span>_</span></div><div class="retro-panel-body">${ownerLeaderboard(5)}</div></section><section class="panel"><div class="ptb"><span>🖱 YOUR SPACE, YOUR CHOICE</span></div><div class="retro-panel-body"><p>Companies, independent projects and individuals all use the same wall.</p><p>Choose a size above, then click anywhere free. Larger blocks can span neighboring free squares.</p><a href="#directory">Browse readable ad profiles →</a></div></section><section class="panel"><div class="ptb"><span>📊 THE DAILY CHALLENGE</span></div><div class="retro-panel-body"><p>Only paid pixel area fills the progress bar. Pending bids never count as revenue.</p><a href="#journey">View progress journal →</a></div></section></aside></div>`;}
function paintWall(){const wall=$('#wall-canvas');if(!wall)return;wall.style.width=`${zoom*100}%`;wall.innerHTML=state.lots.map(l=>{const ad=l.status==='published'?l.ad:null,free=l.status==='available'&&l.side===25;return `<button class="pixel ${free?'free-cell':''} ${l.status==='active'?'active-lot':''} ${l.paidAt?'paid-empty':''}" data-action="lot" data-id="${l.id}" style="left:${l.x/10}%;top:${l.y/10}%;width:${l.side/10}%;height:${l.side/10}%;--tier-bg:#fff;${ad?`background:${ad.color};color:${contrast(ad.color)}`:''}" title="${escape(`${ad?.title||`${l.x}, ${l.y}`} · ${l.side} × ${l.side} · ${statusText(l.status)}`)}" aria-label="${escape(`${l.id}: ${ad?.title||'Position '+l.x+', '+l.y}, ${l.side} by ${l.side}, ${statusText(l.status)}`)}">${ad?.image?`<img src="${ad.image}" alt="" loading="lazy">`:`<span class="pixel-name">${escape(ad?.title||(l.paidAt?'✓':l.status==='active'?'BID ↗':l.side>25?l.side+' × '+l.side:''))}</span>`}</button>`;}).join('')+'<div id="selection-preview" hidden aria-hidden="true"></div>';wall.addEventListener('pointermove',e=>{const b=e.target.closest('.free-cell');if(b)paintSelection(find(b.dataset.id));else $('#selection-preview').hidden=true;});wall.addEventListener('pointerleave',()=>{$('#selection-preview').hidden=true;});}
function contrast(hex){const rgb=hex.slice(1).match(/../g).map(n=>parseInt(n,16));return (rgb[0]*.299+rgb[1]*.587+rgb[2]*.114)>155?'#20265e':'#ffffff';}
function activityList(limit){return state.events.length?state.events.slice(0,limit).map(e=>`<div class="activity-row"><span>${escape(e.message)}</span><time>${ago(e.at)}</time></div>`).join(''):'<div class="empty"><div class="empty-symbol">[ 0 → 1 ]</div><p>The first corner is waiting for its story. Try a demo purchase to see the wall come alive.</p></div>';}
function pageHead(kicker,title,copy,extra=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${copy}</p></div>${extra}</div>`;}
function auctionsPage(){const a=activeAuction();return `${pageHead('PICK YOUR LOCATION. START THE COMPETITION.','Active auctions','100 × 100 placements can be selected anywhere they fit on the shared wall. All buyers have the same access to every location.') }<div class="notice blue">Review edition: bids and payments are simulated in this browser.</div>${a?`<section class="content-card"><div class="auction-layout"><div class="auction-preview"><span class="chip">${escape(a.id)}</span><strong>100 × 100</strong><small>Position: ${a.x}, ${a.y} · 12-month placement</small></div><div class="auction-details">${pill(statusText(a.status))}<h2 style="margin-top:20px">A spot chosen by a real bidder.</h2><p>At least a 10% raise. Last-minute bids leave up to 60 seconds on the timer, capped at 10 extra minutes.</p><div class="timer-box"><div><small>${a.bids.length?'CURRENT BID':'OPENING BID'}</small><strong>${amount(a.amount)}</strong></div><div><small>${a.status==='active'?'ENDS IN':'PAYMENT'}</small><strong ${a.status==='active'?`data-countdown="${a.endsAt}"`:''}>${a.status==='active'?remaining(a.endsAt):'PENDING'}</strong></div></div>${a.status==='active'?action('Place a demo bid ↗','bid',a.id,'dark'):a.winner===state.user?.id?action('Complete demo checkout ↗','pay-winner',a.id,'dark'):'<p>The winner has 24 hours to pay.</p>'}<p>Leading: ${escape(a.bids.at(-1)?.name||'No bids yet')}</p></div></div></section><section class="content-card" style="margin-top:20px"><h3>Bid history</h3>${[...a.bids].reverse().map(b=>`<div class="bid-history"><span>${escape(b.name)}</span><strong>${amount(b.amount)}</strong><span>${ago(b.at)}</span></div>`).join('')||'<p>No bids yet.</p>'}</section>`:`<section class="empty"><h3>No auction is running yet.</h3><p>Select 100 × 100 on the grid, click any free location and open a demo auction there. There is no reserved company district or preassigned auction location.</p>${action('Choose an auction location →','start-demo','','dark')}</section>`}<div class="notice">One featured auction runs at a time in this review model. A winner gets 24 hours to pay. Unpaid wins never count as sales.</div>`;}
function directoryPage(){return `${pageHead('THE PEOPLE BEHIND THE PIXELS','Discover your next favorite.','Readable profiles for every published ad. Small spots on the wall get a proper introduction here.') }<div class="filter-row"><input id="directory-search" class="search-input" type="search" placeholder="Search projects, people and ideas…" aria-label="Search advertisers" value="${escape(search)}">${['all','small','medium','large'].map(f=>`<button class="tab ${directoryFilter===f?'active':''}" data-action="directory-filter" data-id="${f}" aria-pressed="${directoryFilter===f}">${f==='all'?'Everyone':SIZES[f].name}</button>`).join('')}</div><div id="directory-results"></div>`;}
function directoryResults(){const out=$('#directory-results');if(!out)return;const matches=state.lots.filter(l=>l.status==='published'&&l.ad&&(directoryFilter==='all'||l.sizeKey===directoryFilter)&&`${l.ad.title} ${l.ad.description} ${l.ownerName}`.toLowerCase().includes(search.toLowerCase()));out.innerHTML=matches.length?`<div class="card-grid">${matches.map(l=>`<article class="ad-card"><div class="ad-image" style="background:${l.ad.color};color:${contrast(l.ad.color)}">${l.ad.image?`<img src="${l.ad.image}" alt="${escape(l.ad.title)}" loading="lazy">`:escape(l.ad.title.slice(0,16))}</div><div class="ad-card-content">${pill(SIZES[l.sizeKey].name)}<h3>${escape(l.ad.title)}</h3><p>${escape(l.ad.description||'A new neighbor on the wall.')}</p>${action('Meet this project ↗','lot',l.id,'small ghost')}<div style="margin-top:15px;font-size:10px" class="muted">${l.side} × ${l.side} · ${escape(l.ownerName)}</div></div></article>`).join('')}</div>`:`<div class="empty"><div class="empty-symbol">[ hello, world. ]</div><h3>${search?'No matching projects yet.':'Good things start with one.'}</h3><p>${search?'Try another search or a different block size.':'Published profiles will appear here after an ad is approved. Try claiming a demo block, upload your ad, then approve it in the demo studio.'}</p><a href="#wall" class="button dark">Explore the wall ↗</a></div>`;}
function dashboardPage(){if(!state.user)return `${pageHead('YOUR VERY OWN CORNER','Make yourself at home.','Manage your blocks, bids and winning checkouts in one place. You do not have to wait for an email.') }<div class="empty"><h3>A wall profile is all you need.</h3><p>This review version uses a local demo profile. Nothing here creates a real account or charges your card.</p>${action('Create a demo profile ↗','profile','','dark')}</div>`;const u=state.user,owned=state.lots.filter(l=>l.owner===u.id),wins=state.lots.filter(l=>l.status==='awaiting-payment'&&l.winner===u.id),reserved=state.lots.filter(l=>l.status==='reserved'&&l.reservedBy===u.id),bidLots=state.lots.filter(l=>l.bids.some(b=>b.uid===u.id)&&!l.paidAt);return `${pageHead('YOUR PIXELS. YOUR STORY.','Your little corner.','Your claims, bids and checkout reminders—all in one place. Preview activity is stored only in this browser.') }<div class="profile-strip"><span class="profile-avatar">${escape(u.name.slice(0,1).toUpperCase())}</span><div class="grow"><h3>${escape(u.name)}</h3><p>${owned.length} blocks claimed · ${owned.reduce((a,l)=>a+l.side**2,0).toLocaleString()} pixels · local demo profile</p></div>${action('Switch profile','profile','','small ghost')}</div>${wins.map(l=>`<div class="notice pink"><strong>You won ${escape(l.id)} for ${amount(l.amount)}.</strong> Complete checkout within <span data-countdown="${l.deadline}">${remaining(l.deadline)}</span>.<div style="margin-top:12px">${action('Complete demo payment ↗','pay-winner',l.id,'dark small')}</div></div>`).join('')}${reserved.map(l=>`<div class="notice">A checkout for ${escape(l.id)} is reserved until <span data-countdown="${l.deadline}">${remaining(l.deadline)}</span>. ${action('Resume','resume-checkout',l.id,'small ghost')}</div>`).join('')}<div class="section-heading" style="margin-top:25px"><h2>My blocks</h2><a href="#wall">Find another spot ↗</a></div>${owned.length?`<div class="card-grid">${owned.map(l=>`<article class="ad-card"><div class="ad-image" style="background:${l.ad?.color||SIZES[l.sizeKey].color};color:${contrast(l.ad?.color||SIZES[l.sizeKey].color)}">${l.ad?.image?`<img src="${l.ad.image}" alt="">`:escape(l.ad?.title||`${l.side} × ${l.side}`)}</div><div class="ad-card-content">${pill(statusText(l.status),l.status==='published'?'lime':'')}<h3>${escape(l.ad?.title||'Your story starts here.')}</h3><p>${escape(l.id)} · ${SIZES[l.sizeKey].name}<br>Demo paid ${amount(l.amount)} · placement ends ${new Date(l.paidAt+365*86400000).toLocaleDateString('en-GB',{timeZone:'Asia/Dubai'})}</p>${action(l.status==='review'?'Edit submission':'Edit your ad ↗','edit-ad',l.id,'small dark')}${action('View block','lot',l.id,'small ghost')}</div></article>`).join('')}</div>`:`<div class="empty"><h3>Your first piece is waiting.</h3><p>Choose a 25 × 25 or 50 × 50 block on the wall, or place a bid in the featured 100 × 100 auction.</p><a class="button dark" href="#wall">Find my spot ↗</a></div>`}<div class="section-heading"><h2>My bids</h2></div>${bidLots.length?`<div class="table-wrap"><table class="table"><thead><tr><th>BLOCK</th><th>MY LAST BID</th><th>CURRENT PRICE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${bidLots.map(l=>`<tr><td>${escape(l.id)}</td><td>${amount(l.bids.filter(b=>b.uid===u.id).at(-1).amount)}</td><td>${amount(l.amount)}</td><td>${l.status==='active'?(l.bids.at(-1).uid===u.id?'You are leading':'Outbid'):statusText(l.status)}</td><td>${l.status==='active'?action('View auction','go-auctions','','small ghost'):l.winner===u.id?action('Pay','pay-winner',l.id,'small dark'):'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">You have not placed any bids yet.</p>'}`;}
function journeyPage(){const s=stats(state),day=state.campaignStart?Math.floor((Date.now()-state.campaignStart)/86400000)+1:0;return `${pageHead('A WALL BUILT ONE DAY AT A TIME','Day by day. Pixel by pixel.','A public progress journal for the journey to a full wall. Only confirmed payments fill the progress bar.')}${metrics()}<div class="two-col"><section class="content-card"><h3>The daily update</h3><div class="copy-line" id="daily-copy">Day ${day} of filling the Million Pixel Auction.<br>${s.percent.toFixed(2)}% filled. ${s.paidLots} corners claimed.<br>${s.paidPixels.toLocaleString()} / 1,000,000 pixels.<br>Collected: ${money(s.gross)} gross (demo).<br>Who should claim the next spot?</div>${action('Copy daily update ↗','copy-progress','','dark')}<p>These are sample figures from this browser, not real campaign sales. Use verified live data for your published videos.</p></section><section class="activity"><h3>The latest on the wall</h3>${activityList(12)}</section></div>`;}
function howPage(){return `${pageHead('THE ORIGINAL WALL. FREEDOM TO PICK YOUR SPOT.','How it works','One shared 1,000 × 1,000 pixel wall. No buyer categories and no separate company or creator zones.') }<section class="content-card">${[['Choose your block size','25 × 25 costs AED 20. 50 × 50 costs AED 100. 100 × 100 is a featured auction opening at AED 500. Every size is available to every buyer.'],['Pick any free location','Click on the wall to anchor your selection. The highlighted rectangle shows the full footprint. Placements snap to a 25-pixel grid and can cross any neighboring free squares. They cannot overlap existing claims, reservations or auctions.'],['Confirm the placement','Smaller blocks use Buy Now. A 100 × 100 selection can open the featured auction when another auction is not already running. Auction winners pay from My Pixels within 24 hours.'],['Publish your ad','After payment, submit your image, HTTPS link and title for review. Every approved ad also appears in a readable directory.'],['Follow the daily progress','Only confirmed paid area fills the progress bar. The preview simulates every step in this browser and never charges a card.']].map(([t,c],i)=>`<div class="step"><span class="step-number">0${i+1}</span><div><h3>${t}</h3><p>${c}</p></div></div>`).join('')}</section><div class="section-heading"><h2>Choose by size, not by who you are.</h2></div>${tierCards()}`;}
function rulesPage(){return `${pageHead('THE SAME RULES FOR EVERYONE','Wall rules & privacy','Companies, creators and individuals can choose any available position. The only limits are size, price, availability and these rules.') }<div class="two-col"><section class="content-card"><h3>Placements & auctions</h3><ul><li>The wall is 1,000 × 1,000 pixels. Selections snap to 25-pixel increments. No buyer class has exclusive regions.</li><li>25 × 25: AED 20. 50 × 50: AED 100. 100 × 100: auction opening at AED 500.</li><li>Each placement lasts 12 months after confirmed payment. No automatic renewal or guaranteed clicks.</li><li>One featured auction runs at a time for 48 hours. Bids increase at least 10%, rounded up. Last-minute bids extend up to 60 seconds, capped at 10 extra minutes.</li><li>A winner has 24 hours to pay. Unpaid space is released back to the shared wall. A runner-up is never automatically charged.</li><li>No fake bids, owner self-bidding, resale speculation or off-site payment requests.</li></ul><h3>Ad rules</h3><ul><li>Use content you have permission to publish.</li><li>No phishing, malware, impersonation, hate, unlawful products or misleading investment claims.</li><li>Images and links require review. HTTPS destinations only. Approval is not a guarantee that the destination remains safe.</li><li>Visitors can report ads. Changes require review.</li></ul></section><section class="content-card"><h3>About this review edition</h3><p>Names, bids, ads and reports are stored only in this browser. No real account or payment is created. Reset demo clears the data for this revision.</p><p>The live launch still requires an eligible payment provider, trusted server-side ownership and bidding, expiry jobs, operator/contact details and a published refund/privacy policy.</p><p>No payment details or email addresses are collected in this review app. Do not enter confidential information. Google Fonts is used for the original retro typefaces.</p></section></div>`;}
function studioPage(){const s=stats(state),pending=state.lots.filter(l=>l.status==='review'),a=activeAuction();return `${pageHead('THE OWNER’S DESK · LOCAL DEMO','Less admin. More building.','A sample control room for reviewing ads, handling reports and preparing your daily update. This demo studio is visible to everyone; a live studio must enforce admin access on the server.') }<div class="notice pink"><strong>Live payments: closed.</strong> No provider is connected. This review edition cannot take money. The production launch checklist is included in the source handoff.</div><div class="two-col"><div class="stack"><section class="content-card"><h3>Daily publishing</h3><p>Paid area: <strong>${s.percent.toFixed(2)}%</strong> · confirmed demo sales: <strong>${amount(s.gross)}</strong> gross. Outstanding bids stay outside this number.</p><div class="list-inline">${action('Copy daily update','copy-progress','','small dark')}<a class="button small ghost" href="#journey">Public journal ↗</a>${action('Download demo records','export','','small ghost')}</div></section><section class="content-card"><h3>Featured auction</h3>${a?`<p>${escape(a.id)} · ${statusText(a.status)} · ${amount(a.amount)}</p>${a.status==='active'?action('End sample auction now','end-auction',a.id,'small dark'):`<p>Waiting for winner payment until ${new Date(a.deadline).toLocaleString('en-GB',{timeZone:'Asia/Dubai'})} Dubai time.</p>${action('Simulate missed deadline','expire-winner',a.id,'small ghost')}`}`:`<p>There is no featured auction. Start the next 100 × 100 block when you are ready.</p>${action('Open next sample auction','start-demo',state.lots.find(l=>l.status==='upcoming')?.id||'','small dark')}`}<p>These time controls are for testing. Real auction schedules and payment expiries must run on a trusted backend.</p></section><section class="content-card"><h3>Ad review queue · ${pending.length}</h3>${pending.length?pending.map(l=>`<div class="ad-review-preview"><div class="chip">${escape(l.id)}</div><h3 style="margin:12px 0 5px">${escape(l.pendingAd.title)}</h3><p>${escape(l.pendingAd.description)}</p><p class="mono" style="font-size:11px;overflow-wrap:anywhere">${escape(l.pendingAd.url)}</p>${l.pendingAd.image?`<img src="${l.pendingAd.image}" alt="Submitted ad preview">`:''}<p>Owner: ${escape(l.ownerName)}</p><div class="list-inline">${action('Approve demo ad','approve',l.id,'small dark')}${action('Return for revision','reject',l.id,'small ghost')}</div></div>`).join(''):'<p>No ads waiting. Submit a demo ad from My Pixels to try the review flow.</p>'}</section><section class="content-card"><h3>Reports · ${state.reports.filter(r=>!r.resolved).length} open</h3>${state.reports.length?state.reports.map((r,i)=>`<div class="ad-review-preview"><strong>${escape(r.id)} · ${escape(r.reason)}</strong><p>${escape(r.note||'No further details supplied.')}</p><p class="mono" style="font-size:10px">${r.resolved?'Resolved':'Needs review'} · ${ago(r.at)}</p>${!r.resolved?`<div class="list-inline">${action('Hide ad','hide-ad',r.id,'small dark')}${action('Resolve report','resolve-report',String(i),'small ghost')}</div>`:''}</div>`).join(''):'<p>No reports. Visitors can report a published ad from its profile.</p>'}</section></div><aside class="stack"><section class="content-card"><h3>Could the numbers work?</h3><p>There is no fixed buyer mix. A wall filled entirely with 25 × 25 blocks would produce <strong>AED 32,000 gross</strong> at the proposed price. All 50 × 50 blocks would yield AED 40,000; all 100 × 100 blocks at their opening bids would yield AED 50,000. These are full sell-through examples, not forecasts. The calculator below uses the 25 × 25 scenario.</p><div class="form-group"><label for="sell-through">SELL-THROUGH ASSUMPTION</label><input id="sell-through" type="range" min="0" max="100" value="100"><small id="sell-through-value">100% sold, assuming only 25 × 25 blocks</small></div><div class="inline-form"><div class="form-group"><label for="fee-percent">PROCESSING %</label><input id="fee-percent" type="number" min="0" max="20" step="0.1" value="2.9"></div><div class="form-group"><label for="fee-fixed">AED / PAYMENT</label><input id="fee-fixed" type="number" min="0" max="20" step="0.1" value="1"></div></div><div class="inline-form"><div class="form-group"><label for="refund-percent">REFUND RESERVE %</label><input id="refund-percent" type="number" min="0" max="100" value="5"></div><div class="form-group"><label for="annual-hosting">ANNUAL HOSTING AED</label><input id="annual-hosting" type="number" min="0" max="100000" value="0"></div></div><div id="economics"></div><p style="font-size:11px">Planning assumptions only. Excludes licence costs, taxes, your time, disputes, ad creation and other overhead. Processing fees may remain payable on refunds. Auction upside is excluded.</p></section><article class="note-card"><div class="eyebrow">ONE MILLION PIXELS, EXACTLY</div><h3>One shared canvas.</h3><p>Choose any free location, then choose a size. Spaces are allocated as they are claimed. There are no separate zones for companies or individuals.</p></article><article class="note-card pink"><h3>No manual payment claims.</h3><p>In production, only a verified provider event or server-side provider lookup may mark an order paid. A browser button, screenshot or redirect must never transfer ownership.</p></article></aside></div>`;}
function calculate(){const el=$('#economics');if(!el)return;const val=id=>Math.max(0,Number($(id).value)||0),fraction=Math.min(100,val('#sell-through'))/100,estimate=estimateRevenue(Math.min(20,val('#fee-percent')),Math.min(20,val('#fee-fixed')),Math.min(100,val('#refund-percent')),val('#annual-hosting'));const gross=estimate.gross*fraction,fees=estimate.processing*fraction,refunds=estimate.refunds*fraction,total=gross-fees-refunds-estimate.hosting;$('#sell-through-value').textContent=`${Math.round(fraction*100)}% sold, assuming only 25 × 25 blocks`;el.innerHTML=`<div class="summary-row"><span>Gross placement sales</span><strong>${amount(gross)}</strong></div><div class="summary-row"><span>Estimated processing</span><span>− ${amount(fees)}</span></div><div class="summary-row"><span>Refund reserve</span><span>− ${amount(refunds)}</span></div><div class="summary-row"><span>Annual hosting</span><span>− ${amount(estimate.hosting)}</span></div><div class="summary-row total"><span>Before other costs</span><span>${amount(total)}</span></div>`;}
function render(){headerUpdate();retroHeader();const pages={leaderboard:leaderboardPage,badges:badgesPage,ending:auctionsPage,wall:wallPage,auctions:auctionsPage,directory:directoryPage,dashboard:dashboardPage,journey:journeyPage,how:howPage,rules:rulesPage,studio:studioPage,plans:wallPage};main.innerHTML=(pages[route()]||wallPage)();paintWall();directoryResults();calculate();if(route()==='plans')requestAnimationFrame(()=>$('#plans')?.scrollIntoView());}

function lotDialog(id){const l=find(id),t=SIZES[l.sizeKey],ad=l.status==='published'?l.ad:null;modalOpen(`${t.name.toUpperCase()} BLOCK · ${l.id}`,`<h2 id="modal-title">${escape(ad?.title||`${t.name}, with room for you.`)}</h2>${pill(statusText(l.status),l.status==='published'?'lime':'')}<div class="lot-detail-art" style="background:${ad?.color||t.color};color:${contrast(ad?.color||t.color)}">${ad?.image?`<img src="${ad.image}" alt="${escape(ad.title)}">`:escape(ad?.title||`${l.side} × ${l.side}`)}</div>${ad?`<p>${escape(ad.description)}</p><p>Placed by ${escape(l.ownerName)} · ${l.side} × ${l.side} pixels · position ${l.x}, ${l.y}.</p><div class="dialog-actions">${action('Report this ad','report',id,'small ghost')}${action('Visit website ↗','visit',id,'dark')}</div>`:`<p>${t.description} Every published ad also has a readable Discover profile.</p><div class="summary-row"><span>Placement</span><strong>${l.side} × ${l.side} pixels</strong></div><div class="summary-row"><span>${t.mode==='auction'?'Opening / current bid':'One-time price'}</span><strong>${amount(l.amount)}</strong></div><div class="summary-row"><span>Duration</span><strong>12 months after payment</strong></div><div class="dialog-actions">${l.status==='available'?action('Try demo checkout ↗','buy',id,'dark'):l.sizeKey==='large'&&!l.paidAt?action('Explore the auction ↗','go-auctions','','dark'):l.owner===state.user?.id?action('Edit my ad ↗','edit-ad',id,'dark'):'<p>This space is currently reserved or claimed.</p>'}</div>`}`,'lot');}
function buyDialog(id,resume=false){loginThen(()=>run(()=>{const l=resume?find(id):reserve(state,id);if(resume&&(l.reservedBy!==state.user.id||l.status!=='reserved'||l.deadline<=Date.now()))throw Error('This checkout has expired.');save();checkoutLot=id;checkoutDialog(l);}));}
function checkoutDialog(l){modalOpen('DEMO CHECKOUT · NO REAL PAYMENT',`<h2 id="modal-title">Your corner is waiting.</h2><p>${SIZES[l.sizeKey].name} block ${escape(l.id)} · ${l.side} × ${l.side} pixels · position ${l.x}, ${l.y}.</p><div class="summary-row"><span>12-month placement</span><strong>${amount(l.amount)}</strong></div><div class="summary-row"><span>Renewal</span><span>No automatic renewal</span></div><div class="summary-row total"><span>Demo total</span><span>${amount(l.amount)}</span></div><div class="checkout-lock"><strong>No card details. No real charge.</strong><p>Live payments are not connected. The button below simulates a confirmed payment to let you test the complete ownership and ad flow.</p></div><form id="checkout-form" data-id="${l.id}"><label class="check-label"><input name="terms" type="checkbox" required><span>I understand this is a local demo. The proposed offer is 12 months of placement, subject to ad approval, with no guarantee of traffic or returns.</span></label><div class="dialog-actions">${action('Cancel','close','','ghost')}<button class="button dark" type="submit">Simulate payment success ↗</button></div></form><p style="font-size:11px">Reservation expires in <span data-countdown="${l.deadline}">${remaining(l.deadline)}</span>.</p>`,'checkout');}
function bidDialog(id){loginThen(()=>run(()=>{const l=find(id);if(l.status!=='active')throw Error('This auction is closed.');const min=minimumBid(l);modalOpen('FEATURED AUCTION · DEMO BID',`<h2 id="modal-title">Make your next move.</h2><p>100 × 100 100 × 100 block ${escape(id)}. Current ${l.bids.length?'highest bid':'opening price'}: <strong>${amount(l.amount)}</strong>.</p><form id="bid-form" data-id="${id}"><div class="form-group"><label for="bid-amount">YOUR BID IN AED</label><input id="bid-amount" name="bid" type="number" min="${min}" max="1000000" step="1" value="${min}" required><small>Minimum ${money(min)}. At least 10% above the current bid after the first bid.</small></div><label class="check-label"><input type="checkbox" name="confirm" required><span>If I win, I will have 24 hours to complete checkout. This demo does not charge a card.</span></label><div class="notice blue">A bid is a commitment to the displayed amount. Your bid cannot be retracted in this preview.</div><button class="button dark full" type="submit">Confirm demo bid ↗</button></form>`,'bid');}));}
function editDialog(id){run(()=>{const l=find(id);if(l.owner!==state.user?.id||!l.paidAt)throw Error('Only the paid owner can edit this ad.');const ad=l.pendingAd||l.ad||{title:'',description:'',url:'',color:'#2935a3',image:null};uploadedImage=ad.image;modalOpen(`YOUR AD · ${id}`,`<h2 id="modal-title">A small spot. Your big idea.</h2><p>Your ad appears after approval. Use an image you own and a safe HTTPS destination.</p><form id="ad-form" data-id="${id}"><div class="form-group"><label for="ad-title">PROJECT / AD TITLE</label><input id="ad-title" name="title" required minlength="2" maxlength="40" value="${escape(ad.title)}" placeholder="Studio Luna"></div><div class="form-group"><label for="ad-description">YOUR SHORT INTRODUCTION</label><textarea id="ad-description" name="description" maxlength="160" placeholder="What are you making? Who is it for?">${escape(ad.description)}</textarea></div><div class="form-group"><label for="ad-url">WEBSITE ADDRESS</label><input id="ad-url" name="url" type="url" required value="${escape(ad.url)}" placeholder="https://example.com"></div><div class="inline-form"><div class="form-group"><label for="ad-color">BACKGROUND COLOR</label><input id="ad-color" name="color" type="color" value="${ad.color}"></div><div class="form-group"><label for="ad-image">OPTIONAL IMAGE</label><input id="ad-image" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG or WebP. Maximum 5 MB input; resized locally to 256 px.</small></div></div><div id="image-preview" ${ad.image?'':'hidden'}>${ad.image?`<img src="${ad.image}" alt="Selected ad image" style="max-height:100px;max-width:100%">`:''}</div><button type="button" class="tab" data-action="remove-image">Remove image</button><div class="form-group"><label class="check-label"><input name="rights" type="checkbox" required><span>I have permission to use this content, and it follows the <a href="#rules">wall rules</a>.</span></label></div><button class="button dark full" type="submit">Submit ad for review ↗</button></form>`,'ad');});}
function reportDialog(id){modalOpen('KEEP THE WALL SAFE',`<h2 id="modal-title">Something doesn’t look right?</h2><p>Report block ${escape(id)} for review. Demo reports appear in the local Owner Studio.</p><form id="report-form" data-id="${escape(id)}"><div class="form-group"><label for="report-reason">REASON</label><select id="report-reason" name="reason"><option>Suspicious or misleading link</option><option>Impersonation</option><option>Copyright or content rights</option><option>Inappropriate content</option><option>Other</option></select></div><div class="form-group"><label for="report-note">OPTIONAL DETAILS</label><textarea id="report-note" name="note" maxlength="400" placeholder="Please do not include private information."></textarea></div><button type="submit" class="button dark full">Submit demo report</button></form>`,'report');}
function visitDialog(id){const ad=find(id).ad,u=safeUrl(ad?.url);if(!u)throw Error('This link is unavailable.');modalOpen('YOU ARE LEAVING THE WALL',`<h2 id="modal-title">Meet ${escape(ad.title)}.</h2><p>This is an independent advertiser’s website. Ad approval does not guarantee the safety or claims of the destination.</p><div class="notice mono" style="overflow-wrap:anywhere">${escape(u)}</div><div class="dialog-actions">${action('Stay here','close','','ghost')}<a class="button dark" href="${escape(u)}" target="_blank" rel="noopener noreferrer nofollow sponsored">Continue to website ↗</a></div>`);}
async function copyProgress(){const s=stats(state),day=state.campaignStart?Math.floor((Date.now()-state.campaignStart)/86400000)+1:0,text=`Day ${day} of filling the Million Pixel Auction.\n${s.percent.toFixed(2)}% filled. ${s.paidLots} corners claimed.\n${s.paidPixels.toLocaleString()} / 1,000,000 pixels.\nCollected: ${money(s.gross)} gross (DEMO, not real sales).\nWho should claim the next spot?`;try{await navigator.clipboard.writeText(text);toast('Demo daily update copied.');}catch{modalOpen('DAILY UPDATE',`<h2 id="modal-title">Your update, ready to copy.</h2><textarea class="search-input" style="width:100%;max-width:100%;height:170px" readonly>${escape(text)}</textarea>`);}}
function exportRecords(){const blob=new Blob([JSON.stringify({...state,user:state.user?{name:state.user.name,id:state.user.id}:null,warning:'LOCAL DEMO DATA. NOT REAL SALES.'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='million-pixel-demo-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Demo records downloaded.');}

document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn)return;const {action:act,id}=btn.dataset;run(()=>{switch(act){case 'choose-wall-size':selectedSize=id;modalClose();location.hash='wall';render();break;case 'close':modalClose();break;case 'lot':{const l=find(id);if(l.status==='available'&&l.side===25)placementDialog(l);else lotDialog(id);break;}case 'profile':profileDialog();break;case 'switch-user':{const after=returnAction;state.user={id,name:id==='alex'?'Alex':'Sam'};modalClose();commit(`Demo profile switched to ${state.user.name}.`);returnAction=null;after?.();break;}case 'sign-out':modalClose();state.user=null;commit('Signed out of the local demo.');break;case 'reset-confirm':checkoutLot=null;state=freshState();zoom=1;search='';modalClose();commit('A fresh demo canvas is ready.');break;case 'wall-filter':wallFilter=id;render();break;case 'size-tool':selectedSize=id;render();break;case 'select-size':selectedSize=id;placementDialog(selectionAnchor);paintSelection(selectionAnchor);break;case 'confirm-placement':confirmPlacement();break;case 'goto-position':gotoPosition();break;case 'go-wall':modalClose();location.hash='wall';break;case 'directory-filter':directoryFilter=id;render();break;case 'zoom-in':zoom=Math.min(4,zoom+.5);render();break;case 'zoom-out':zoom=Math.max(1,zoom-.5);render();break;case 'pick-tier':if(route()!=='wall')location.hash='wall';wallFilter=id;render();requestAnimationFrame(()=>$('#wall-scroll')?.scrollIntoView({block:'center'}));lotDialog(state.lots.find(l=>l.sizeKey===id&&l.status==='available')?.id||state.lots.find(l=>l.sizeKey===id).id);break;case 'go-auctions':modalClose();location.hash='auctions';break;case 'buy':buyDialog(id);break;case 'resume-checkout':buyDialog(id,true);break;case 'pay-winner':loginThen(()=>{const l=find(id);if(l.winner!==state.user.id||l.status!=='awaiting-payment')throw Error('This winning checkout belongs to another profile.');checkoutLot=null;checkoutDialog(l);});break;case 'bid':bidDialog(id);break;case 'edit-ad':editDialog(id);break;case 'start-demo':if(!id){selectedSize='large';location.hash='wall';render();toast('Click any free part of the wall to place a 100 × 100 auction.');break;}startAuction(state,id);modalClose();commit('Sample auction opened for 48 hours.');location.hash='auctions';break;case 'show-leaderboard':location.hash='leaderboard';break;case 'show-badges':location.hash='badges';break;case 'end-auction':{const l=find(id);l.endsAt=Date.now()-1;expire(state);commit('Sample auction ended. Unpaid wins do not count as sales.');break;}case 'expire-winner':find(id).deadline=Date.now()-1;expire(state);commit('Unpaid winner expired. The 100 × 100 block is back in the queue.');break;case 'approve':approveAd(state,id);commit('Demo ad approved and published.');break;case 'reject':rejectAd(state,id);commit('Ad returned to the owner for revision.');break;case 'report':reportDialog(id);break;case 'visit':visitDialog(id);break;case 'hide-ad':find(id).status='hidden';commit('Ad hidden from the public wall and directory.');break;case 'resolve-report':state.reports[Number(id)].resolved=true;commit('Report marked resolved.');break;case 'copy-progress':copyProgress();break;case 'export':exportRecords();break;case 'remove-image':uploadedImage=null;$('#image-preview').innerHTML='';$('#image-preview').hidden=true;$('#ad-image').value='';break;}});});
document.addEventListener('submit',e=>{if(!e.target.matches('#profile-form,#checkout-form,#bid-form,#ad-form,#report-form'))return;e.preventDefault();const form=e.target,data=new FormData(form),id=form.dataset.id;try{if(form.id==='profile-form'){const name=String(data.get('name')).trim();if(name.length<2||name.length>24)throw Error('Use a name between 2 and 24 characters.');const after=returnAction;state.user={id:state.user?.id||crypto.randomUUID(),name};modalClose();returnAction=null;commit('Your local demo profile is ready.');after?.();}else if(form.id==='checkout-form'){simulatePayment(state,id);checkoutLot=null;modalClose();commit('Demo payment confirmed. Your block is ready for an ad.');if(route()==='dashboard')editDialog(id);else{afterNavigation=()=>editDialog(id);location.hash='dashboard';}}else if(form.id==='bid-form'){placeBid(state,id,Number(data.get('bid')));modalClose();commit('Demo bid placed. Track your status in My Pixels.');}else if(form.id==='ad-form'){submitAd(state,id,{title:String(data.get('title')),description:String(data.get('description')),url:String(data.get('url')),color:String(data.get('color')),image:uploadedImage});modalClose();commit('Submitted for review. Try approving it in the demo Owner Studio.');}else if(form.id==='report-form'){if(state.reports.some(r=>r.id===id&&!r.resolved))throw Error('This block already has an open report in this demo.');state.reports.unshift({id,reason:String(data.get('reason')),note:String(data.get('note')).slice(0,400),at:Date.now(),resolved:false});modalClose();commit('Demo report submitted. Find it in the Owner Studio.');}}catch(err){let error=form.querySelector('.error');if(!error){error=document.createElement('div');error.className='error';error.setAttribute('role','alert');form.prepend(error);}error.textContent=err.message;}});
document.addEventListener('input',e=>{if(e.target.id==='directory-search'){search=e.target.value;directoryResults();}if(['sell-through','fee-percent','fee-fixed','refund-percent','annual-hosting'].includes(e.target.id))calculate();});
document.addEventListener('change',async e=>{if(e.target.id!=='ad-image')return;const file=e.target.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Choose a PNG, JPEG or WebP image under 5 MB.');const image=await createImageBitmap(file);const scale=Math.min(1,256/Math.max(image.width,image.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(image.width*scale));c.height=Math.max(1,Math.round(image.height*scale));c.getContext('2d').drawImage(image,0,0,c.width,c.height);image.close();const imageData=c.toDataURL('image/webp',.8);if(imageData.length>190000)throw Error('That image is too complex. Try a simpler image.');if(activeDialog!=='ad')return;uploadedImage=imageData;$('#image-preview').hidden=false;$('#image-preview').innerHTML=`<img src="${uploadedImage}" alt="Selected ad image" style="max-height:100px;max-width:100%">`;toast('Image resized and ready.');}catch(err){e.target.value='';toast(err.message);}});
setInterval(()=>{if(expire(state)){save();if(modal.open){checkoutLot=null;modalClose();toast('A reservation or auction deadline changed. Please check its current status.');}render();}document.querySelectorAll('[data-countdown]').forEach(el=>el.textContent=remaining(Number(el.dataset.countdown)));},1000);
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){checkoutLot=null;modal.close();load();render();toast('Demo activity updated from another tab.');}});
render();

function retroHeader(){const s=stats(state);$('#h-sold').textContent=s.paidLots;$('#h-bids').textContent=s.bids;$('#h-rev').textContent=money(s.gross);$('#vis-cnt').textContent=String(s.paidPixels).padStart(8,'0');$('#prog-fill').style.width=s.percent+'%';$('#prog-pct').textContent=s.percent.toFixed(2)+'%';$('#h-day').textContent=state.campaignStart?'DAY '+(Math.floor((Date.now()-state.campaignStart)/86400000)+1):'DAY 0';$('#selection-status').textContent=`${SIZES[selectedSize].name} selected · choose any free position · no separate buyer zones`;}
function paintSelection(anchor){const el=$('#selection-preview');if(!el||!anchor)return;const size=SIZES[selectedSize].side,valid=canPlace(state,anchor.x,anchor.y,selectedSize);el.hidden=false;el.classList.toggle('invalid',!valid);el.style.left=anchor.x/10+'%';el.style.top=anchor.y/10+'%';el.style.width=Math.min(size,1000-anchor.x)/10+'%';el.style.height=Math.min(size,1000-anchor.y)/10+'%';el.textContent=valid?`${size} × ${size}`:'DOES NOT FIT';$('#selection-status').textContent=`Position ${anchor.x}, ${anchor.y} · ${size} × ${size} · ${valid?'Available':'Overlaps a claim or wall boundary'}`;}
function placementDialog(anchor){if(!anchor)return;selectionAnchor={x:anchor.x,y:anchor.y};const t=SIZES[selectedSize],valid=canPlace(state,anchor.x,anchor.y,selectedSize);modalOpen('CHOOSE YOUR PLACEMENT',`<h2 id="modal-title">Your spot. Your size.</h2><p>This location is available to everyone. Choose a block size; its top-left corner stays at pixel <strong>${anchor.x}, ${anchor.y}</strong>.</p><div class="size-options">${Object.entries(SIZES).map(([key,size])=>`<button class="size-option ${key===selectedSize?'active':''}" data-action="select-size" data-id="${key}" aria-pressed="${key===selectedSize}"><strong>${size.name}</strong><small>${key==='large'?'Auction from ':''}${amount(size.price)}</small></button>`).join('')}</div><div class="placement-map ${valid?'':'invalid'}">${t.name} pixels at ${anchor.x}, ${anchor.y}<br>${valid?'✓ Fits here — no overlap':'✕ Does not fit here. Choose a smaller size or another position.'}</div><p>${selectedSize==='large'?'Open a 48-hour auction at this exact location. One featured auction runs at a time.':'One-time Buy Now price. No bidding required for this size.'} All placements last 12 months from confirmed payment.</p><div class="dialog-actions">${action('Choose elsewhere','close','','ghost')}<button class="button dark" data-action="confirm-placement" ${valid?'':'disabled'}>${selectedSize==='large'?'Open demo auction here →':'Continue to demo checkout →'}</button></div>`,'placement');paintSelection(anchor);}
function confirmPlacement(){const anchor={...selectionAnchor},sizeKey=selectedSize;if(!canPlace(state,anchor.x,anchor.y,sizeKey))throw Error('That position is no longer free.');if(sizeKey==='large'&&activeAuction())throw Error('Another featured auction is already running. You can bid there, or select a Buy Now size here.');loginThen(()=>run(()=>{const l=selectPlacement(state,anchor.x,anchor.y,sizeKey);if(sizeKey==='large'){startAuction(state,l.id);modalClose();commit('Demo auction opened at your chosen position.');location.hash='auctions';}else{save();buyDialog(l.id);}}));}
function gotoPosition(){const value=Number($('#goto-cell')?.value);if(!Number.isInteger(value)||value<0||value>1599)throw Error('Enter a cell number from 0 to 1599.');const x=value%40*25,y=Math.floor(value/40)*25;const existing=state.lots.find(l=>x>=l.x&&x<l.x+l.side&&y>=l.y&&y<l.y+l.side);if(!existing)throw Error('This position is unavailable.');if(existing.status==='available'&&existing.side===25)placementDialog(existing);else lotDialog(existing.id);}
function retroAuction(){const a=activeAuction();if(!a)return `<p>No active auction yet.</p><p>Select 100 × 100, then click anywhere free on the grid.</p>${action('Pick a location →','start-demo','','small dark')}`;return `<p><strong>${escape(a.id)}</strong><br>At ${a.x}, ${a.y} · 100 × 100</p><div class="retro-auction-price">${amount(a.amount)}</div><p>${a.status==='active'?`<span data-countdown="${a.endsAt}">${remaining(a.endsAt)}</span> remaining`:'Winner payment pending'}</p><a href="#auctions">View auction →</a>`;}
function owners(){const map=new Map();for(const l of state.lots.filter(l=>l.paidAt&&l.owner)){const owner=map.get(l.owner)||{name:l.ownerName,pixels:0,blocks:0};owner.pixels+=l.side**2;owner.blocks++;map.set(l.owner,owner);}return [...map.values()].sort((a,b)=>b.pixels-a.pixels);}
function ownerLeaderboard(limit){const list=owners().slice(0,limit);return list.length?list.map((o,i)=>`<div class="owner-row"><span>${i+1}.</span><strong>${escape(o.name)}</strong><span>${o.pixels.toLocaleString()} px</span></div>`).join(''):'<div class="empty-msg">No paid owners yet.<br>Claim any free spot to join.</div>';}
function leaderboardPage(){return `${pageHead('THE PEOPLE FILLING THE WALL','Leaderboard','Ranked by paid pixel area. Every size and every buyer has the same access to the shared wall.') }<div class="owner-leaderboard">${ownerLeaderboard(100)}</div>`;}
function badgesPage(){const mine=state.lots.filter(l=>l.owner===state.user?.id&&l.paidAt),bidder=state.user&&state.lots.some(l=>l.bids.some(b=>b.uid===state.user.id));return `${pageHead('A LITTLE FUN ALONG THE WAY','Badges','Local demo achievements for joining the wall, bidding and publishing your story.') }<div class="badge-list">${[['🧱','First Corner','Claim a paid block.',mine.length>0],['🔨','Auction Explorer','Place a demo auction bid.',bidder],['🖼','On the Wall','Publish an approved ad.',mine.some(l=>l.status==='published')],['📐','Room to Grow','Claim a 50 × 50 or larger block.',mine.some(l=>l.side>=50)]].map(([icon,name,desc,unlocked])=>`<div class="badge-card ${unlocked?'':'locked'}"><span class="badge-icon">${icon}</span><strong>${name}</strong><p>${desc}</p><p>${unlocked?'✓ UNLOCKED':'LOCKED'}</p></div>`).join('')}</div>`;}

